<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/certificate-auth.php';
$user=fleet_cert_require_user();fleet_cert_require_permission($user,'roles.manage');$db=fleet_db();$catalog=fleet_cert_permission_catalog();$allPages=$catalog['pages'];$allPermissions=array_merge(array_keys($catalog['pages']),array_keys($catalog['actions']));
try{
 if(($_SERVER['REQUEST_METHOD']??'GET')==='GET'){
  $roles=$db->query('SELECT id,role_name,description,permissions_json,menu_order_json FROM roles ORDER BY role_name')->fetchAll();foreach($roles as &$r){$r['permissions']=json_decode((string)$r['permissions_json'],true)?:[];$r['menu_order']=json_decode((string)$r['menu_order_json'],true)?:[];$r['built_in']=in_array($r['role_name'],['ADMIN','APP_CONTROLLER'],true);unset($r['permissions_json'],$r['menu_order_json']);}unset($r);
  $users=$db->query('SELECT u.id,u.full_name,u.username,u.email,u.is_active,MIN(ur.role_id) role_id,GROUP_CONCAT(r.role_name ORDER BY r.role_name SEPARATOR ", ") roles FROM users u LEFT JOIN user_roles ur ON ur.user_id=u.id LEFT JOIN roles r ON r.id=ur.role_id GROUP BY u.id ORDER BY u.full_name')->fetchAll();
  json_response(['ok'=>true,'roles'=>$roles,'users'=>$users,'catalog'=>$catalog]);
 }
 fleet_cert_require_same_origin_post();$in=json_decode((string)file_get_contents('php://input'),true);if(!is_array($in))json_response(['ok'=>false,'message'=>'Invalid access-control request.'],400);$action=(string)($in['action']??'');$actor=(int)$user['id'];$db->beginTransaction();
 if($action==='save_role'||$action==='create_role'){
  $id=(int)($in['role_id']??0);$name=trim((string)($in['role_name']??''));$description=trim((string)($in['description']??''));$key=strtoupper(trim((string)preg_replace('/[^A-Za-z0-9]+/','_',$name),'_'));
  if($name===''||mb_strlen($name)>80||$description!==''&&mb_strlen($description)>255)throw new InvalidArgumentException('Enter a role name up to 80 characters and a description up to 255 characters.');
  if(in_array($key,['ADMIN','REVIEWER','VIEWER','OPERATOR','EDITOR_ONLY'],true))$key=in_array($key,['EDITOR_ONLY'],true)?$key:$key;
