  $menu=is_array($in['menu_order']??null)?$in['menu_order']:[];$menu=array_values(array_unique(array_filter(array_map('strval',$menu),fn($v)=>isset($allPages['page.'.$v])&&in_array('page.'.$v,$permissions,true))));
