  else{$q=$db->prepare('SELECT role_name FROM roles WHERE id=? FOR UPDATE');$q->execute([$id]);$old=$q->fetchColumn();if(!$old)throw new InvalidArgumentException('Select a role that still exists.');if($old==='APP_CONTROLLER')throw new InvalidArgumentException('App Controller permissions cannot be edited.');if($old==='ADMIN'&&$key!=='ADMIN')throw new InvalidArgumentException('The built-in Admin role name cannot be changed.');if($old!=='ADMIN'&&(in_array('roles.manage',$permissions,true)||in_array('users.manage',$permissions,true)))throw new InvalidArgumentException('Only the App Controller role can create roles or assign access.');$q=$db->prepare('UPDATE roles SET role_name=?,description=?,permissions_json=?,menu_order_json=? WHERE id=?');$q->execute([$key,$description?:null,json_encode($permissions,JSON_THROW_ON_ERROR),json_encode($menu,JSON_THROW_ON_ERROR),$id]);$verb='Updated';}
  fleet_cert_log($db,$actor,strtoupper($action),'ROLE',$id,$verb.' role '.$key.' with '.count($permissions).' permissions.');$db->commit();json_response(['ok'=>true,'message'=>'Role saved. Changes take effect on the next request.','role_id'=>$id]);
