 if($action==='delete_role'){$id=(int)($in['role_id']??0);$q=$db->prepare('SELECT role_name FROM roles WHERE id=? FOR UPDATE');$q->execute([$id]);$name=$q->fetchColumn();if(!$name||in_array($name,['ADMIN','APP_CONTROLLER'],true))throw new InvalidArgumentException('Built-in ADMIN and APP_CONTROLLER roles cannot be deleted.');$q=$db->prepare('SELECT COUNT(*) FROM user_roles WHERE role_id=?');$q->execute([$id]);if((int)$q->fetchColumn())throw new InvalidArgumentException('Reassign users from this role before deleting it.');$db->prepare('DELETE FROM roles WHERE id=?')->execute([$id]);fleet_cert_log($db,$actor,'DELETE','ROLE',$id,'Deleted unused role '.$name.'.');$db->commit();json_response(['ok'=>true,'message'=>'Unused role deleted.']);}
 if($action==='assign_user_role'){$userId=(int)($in['user_id']??0);$roleId=(int)($in['role_id']??0);$q=$db->prepare('SELECT id,is_active FROM users WHERE id=? FOR UPDATE');$q->execute([$userId]);$target=$q->fetch();$q=$db->prepare('SELECT role_name FROM roles WHERE id=?');$q->execute([$roleId]);$roleName=$q->fetchColumn();if(!$target||!$roleName)throw new InvalidArgumentException('Select a valid user and role.');if($userId===$actor&&$roleName!=='APP_CONTROLLER'){$q=$db->prepare("SELECT COUNT(*) FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE u.is_active=1 AND r.role_name='APP_CONTROLLER' AND u.id<>?");$q->execute([$userId]);if(!(int)$q->fetchColumn())throw new InvalidArgumentException('You cannot remove the last active App Controller from your own account.');}$db->prepare('DELETE FROM user_roles WHERE user_id=?')->execute([$userId]);$db->prepare('INSERT INTO user_roles(user_id,role_id) VALUES(?,?)')->execute([$userId,$roleId]);fleet_cert_log($db,$actor,'ASSIGN_ROLE','USER',$userId,'Assigned role '.$roleName.'.');$db->commit();json_response(['ok'=>true,'message'=>'User role updated. It applies on the next request.']);}
 throw new InvalidArgumentException('Choose a valid access-control action.');
}catch(InvalidArgumentException $e){if($db->inTransaction())$db->rollBack();json_response(['ok'=>false,'message'=>$e->getMessage()],400);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Access control: '.$e->getMessage());json_response(['ok'=>false,'message'=>'The access-control change could not be saved. No changes were applied.'],500);}
